import { create } from 'zustand';

const useAppStore = create((set) => ({
  theme: 'dark',
  cart: [],
  addToCart: (item) => set((s) => ({ cart: [...s.cart, item] })),
}));

function ThemeBadge() {
  const theme = useAppStore((s) => s.theme);        // селектор
  return <span>{theme}</span>;
}
function CartCount() {
  const count = useAppStore((s) => s.cart.length);  // селектор
  return <span>{count}</span>;
}

