function useStreamingMessages(initial) {
  const [messages, setMessages] = useState(initial);
  const buffer = useRef('');   // сюда копятся куски между кадрами
  const frame = useRef(0);

  const flush = useCallback(() => {
    frame.current = 0;
    const chunk = buffer.current;
    buffer.current = '';
    setMessages((prev) => {
      const last = prev[prev.length - 1];
      // новый объект только у последнего сообщения, остальные те же ссылки
      return [...prev.slice(0, -1), { ...last, text: last.text + chunk }];
    });
  }, []);

  const onChunk = useCallback((chunk) => {
    buffer.current += chunk;              // ref: без рендера
    if (!frame.current) frame.current = requestAnimationFrame(flush);
  }, [flush]);

  return { messages, onChunk };
}

